    code: |-
      /* @display
      Value To Check: undefined
      Default Value: default
      @output
      default
      */
      const src = undefined;
      const def = "default";
      const mockData = {
          src: src,
          def: def,
          rp1: false
      };
      let variableResult;
      if (isDirectMode) {
          variableResult = runCode(mockData);
